mapper.sql:
where 1=1

		and cdrg_llave = #{llaveTabla}


		and cdrg_estado = #{estado}


		and cdrg_documentoprincipal = #{documentoPrincipal}


		and cdrg_documentomodificador = #{documentoModificador}


		and ddrg_fecha >= #{fechaMin}


		and ddrg_fecha  <   #{fechaMax}


		and cdrg_estadoinicial = #{estadoInicial}


		and cdrg_estadofinal = #{estadoFinal}


		and cdrg_usuario = #{usuario}


		and cdrg_ubicacion = #{ubicacion}


		and cdrg_valores = #{valores}


		and cdrg_transaccion = #{transaccion}


		and ddrg_cierre >= #{cierreMin}


		and ddrg_cierre  <   #{cierreMax}


		and cdrg_nombre = #{nombre}


		and bdrg_estadorepetido = #{estadorepetidoFilter}

mapper.select:
select cdrg_llave as llaveTabla ,cdrg_documentoprincipal as documentoPrincipal ,cdrg_documentomodificador as documentoModificador ,ddrg_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadofinal) as estadoFinal ,cdrg_estado as estado ,cdrg_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cdrg_usuario) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cdrg_usuario) as responsableImagen ,modifica.cpdv_nombre as modificadorNombre ,descripcion(modifica.cpdv_llave) as comentario ,modifica.cpdv_plantilla as plantilla ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = modifica.cpdv_plantilla) as plantillaNombre ,(select mpvd_saldo from pedidoventadinero_pvdpz_pvd_pedidoventadinero where cpvd_llave = cdrg_valores) as saldo ,(select mpvd_valortotal from pedidoventadinero_pvdpz_pvd_pedidoventadinero where cpvd_llave = cdrg_valores) as total ,cdrg_ubicacion as ubicacion ,descripcion(cdrg_ubicacion) as ubicacionNombre ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = (select cpdv_plantilla from pedidoventa_pdvp where cpdv_llave = cdrg_ubicacion)) as ubicacionPlantilla ,cdrg_nombre as nombre ,cdrg_transaccion as transaccion ,(select cpvc_valortext from campo4id ( cdrg_documentomodificador , (select cppd_valor from propiedad_ppdp where cppd_propiedadvalor = 'PROP_178' and cppd_estado = 'A' and cppd_tipo = 'L' and cppd_campo = (select cpdv_plantilla from pedidoventa_pdvp where cpdv_llave = cdrg_documentomodificador)), modifica.npdv_historico)) as adjunto from documentorelaciongestor_drgpz_drg_documentorelaciongestor left join pedidoventa_pdvp modifica on (cpdv_llave = cdrg_documentomodificador) where cdrg_documentoprincipal = #{dto.documentoPrincipal} and cdrg_usuario != #{usuarioAutomatico}
union select cact_llave as llaveTabla ,cact_llave as documentoPrincipal ,null as documentoModificador ,dact_fecharegistro as fecha ,null as estadoInicial ,null as estadoFinal ,null as estado ,cact_usuarioregistro as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cact_usuarioregistro) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cact_usuarioregistro) as responsableImagen ,null as modificadorNombre ,cact_comentario as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,(select 'Asignado a ' || cusr_nombre from usuario_usrp where cusr_llave = cact_responsable) as nombre ,null as transaccion ,null as adjunto from actividad_actp where cact_documento = #{dto.documentoPrincipal} union select cpva_llave as llaveTabla ,cpva_llave as documentoPrincipal ,null as documentoModificador ,dpva_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadofinal) as estadoFinal ,null as estado ,cpva_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cpva_responsable) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cpva_responsable) as responsableImagen ,null as modificadorNombre ,cpva_motivo as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,null as nombre ,null as transaccion ,null as adjunto from pedidoventaajuste_pvap where cpva_documento = #{dto.documentoPrincipal}
union select cmsj_llave as llaveTabla ,cmsj_documento as documentoPrincipal ,null as documentoModificador ,dmsj_fecha as fecha ,null as estadoInicial ,cmsj_correo as estadoFinal ,null as estado ,cmsj_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = (select corg_usuariosystem from organizacion_orgp oo where corg_estado = 'A' and corg_principal is null)) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = (select corg_usuariosystem from organizacion_orgp oo where corg_estado = 'A' and corg_principal is null)) as responsableImagen ,null as modificadorNombre ,cmsj_titulo as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,CASE WHEN dmsj_correoenviado IS NULL THEN 'Mensaje sin correo enviado al destinatario ' || (select cusr_nombre from usuario_usrp where cusr_llave = cmsj_usuario) ELSE CASE WHEN cmsj_correoerror IS NULL THEN 'Mensaje enviado el ' || to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') || ' a ' || (select cusr_nombre from usuario_usrp where cusr_llave = cmsj_usuario) ELSE to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') || cmsj_correoerror END END as nombre ,null as transaccion ,cmsj_adjuntourl as adjunto from mensaje_msjp where cmsj_documento = #{dto.documentoPrincipal}
union select ctpi_llave as llaveTabla ,cdpr_documento as documentoPrincipal ,cpro_documento as documentoModificador ,dtpi_fecha as fecha ,(select descripcion(cbod_documento) from bodega_bodp where cbod_llave = ctpi_bodega) as estadoInicial ,null as estadoFinal ,null as estado ,ctpi_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = ctpi_responsable) as responsable ,null as responsableImagen ,null as modificadorNombre ,('[ Inician : ' || mtpi_cantidadinicial || '] Se mueve inventario de: ' || mtpi_cantidad || ' => Terminan : ' || mtpi_cantidadfinal) as comentario ,cpdv_plantilla as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,descripcion(cpro_documento) as nombre ,null as transaccion ,null as adjunto from trazabilidadproductoinventario_tpip inner join deduccionproducto_dprp on (cdpr_llave = ctpi_deduccionproducto ) inner join producto_prop on (cpro_llave = ctpi_producto) inner join pedidoventa_pdvp on (cpdv_llave = cpro_documento) where cdpr_documento = #{dto.documentoPrincipal}
union select cwse_llave as llaveTabla ,cwse_documento as documentoPrincipal ,null as documentoModificador ,case when dwse_fechaejecucion is not null then dwse_fechaejecucion else dwse_fecha end as fecha ,null as estadoInicial ,(select cwbs_nombre from webservice_wbsp where cwbs_llave = cwse_servicio) as estadoFinal ,null as estado ,cwse_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cwse_usuario) as responsable ,null as responsableImagen ,null as modificadorNombre ,cwse_error as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,null as nombre ,null as transaccion ,case when cwse_masivo is not null then (cwse_entrada || ';;' || cwse_salida || ';;' || cwse_masivo) else (cwse_entrada || ';;' || cwse_salida) end as adjunto from webserviceejecucion_wsep where cwse_documento = #{dto.documentoPrincipal}
union select crej_llave as llaveTabla ,crej_documento as documentoPrincipal ,null as documentoModificador ,drej_fechainicio as fecha ,'Impresion de reporte' as estadoInicial ,(drej_fechafin - drej_fechainicio)::text as estadoFinal ,null as estado ,crej_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = crej_usuario) as responsable ,null as responsableImagen ,null as modificadorNombre ,crej_error as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,(select crpb_nombre from reportebase_rpbp where crpb_llave = crej_reporte) as nombre ,null as transaccion ,crej_url as adjunto from reporteejecucion_rejpz_rej_reporteejecucion where crej_documento = #{dto.documentoPrincipal}
order by fecha desc LIMIT #{dto.paginacionRegistroFinal} OFFSET #{dto.paginacionRegistroInicial}
